// src/pages/SDM.jsx
import React, { useState, useEffect, useRef } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import Card from "../components/common/Card";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import { topicDescriptions } from "../constants/sdm";
import styles from "../SDM.module.css";
import Paper from "../components/common/Paper";

import eveVideo from "../assets/eve_sdm_talk.mp4";

const SDM = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const [searchParams, setSearchParams] = useSearchParams();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const step = searchParams.get("step") || "SELECT";
  const selectedKey = searchParams.get("topic") || null;
  const currentTopic = topicDescriptions[selectedKey];

  // 1. 關鍵：清空 HeroData 標題，專注於卡片內部排版
  // src/pages/SDM.jsx
  useEffect(() => {
    // 直接設為 null 隱藏外層大頭貼
    setHeroData(null);

    const speechText =
      step === "INTRO"
        ? currentTopic?.content
        : "請選擇您想了解的主題。點選下方以查看詳細的手術決策資訊。";

    if (speechText) {
      handlePlaySpeech(speechText);
    }

    window.scrollTo(0, 0);

    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [step, currentTopic, setHeroData]);

  const handlePlaySpeech = (rawText) => {
    if (!window.speechSynthesis || !videoRef.current || !rawText) return;

    window.speechSynthesis.cancel();
    const pureText = rawText.replace(/<[^>]*>/g, "").trim();

    const utterance = new SpeechSynthesisUtterance(pureText);
    utterance.lang = "zh-TW";
    utterance.rate = step === "INTRO" ? 0.95 : 1.0;

    utterance.onstart = () => {
      setIsPlaying(true);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.muted = true;
        videoRef.current.play().catch((err) => console.log(err));
      }
    };

    utterance.onend = () => {
      setIsPlaying(false);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0;
      }
    };

    window.speechSynthesis.speak(utterance);
  };

  // ⏸️ 暫停控制
  const handleTogglePlay = (e) => {
    e.stopPropagation();
    if (!window.speechSynthesis) return;

    if (isPlaying && !isPaused) {
      window.speechSynthesis.pause();
      if (videoRef.current) videoRef.current.pause();
      setIsPaused(true);
    } else if (isPlaying && isPaused) {
      window.speechSynthesis.resume();
      if (videoRef.current)
        videoRef.current.play().catch((err) => console.log(err));
      setIsPaused(false);
    } else {
      const speechText =
        step === "INTRO"
          ? currentTopic?.content
          : "請選擇您想了解的主題。點選下方以查看詳細的手術決策資訊。";
      handlePlaySpeech(speechText);
    }
  };

  const handleSelectCard = (key) =>
    setSearchParams({ step: "SELECT", topic: key });

  const handleConfirmTopic = () => {
    if (!selectedKey) return alert("請先選擇一個方案");
    setAllAnswers((prev) => ({ ...prev, selectedTopic: currentTopic.label }));
    setSearchParams({ step: "INTRO", topic: selectedKey });
  };

  const handleStartQuiz = () => {
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    navigate(`/questionnaire/${selectedKey}`);
  };

  return (
    <div className={styles.pageContainer}>
      <div className={styles.interactiveCard}>
        {/* 頂部影片區 */}
        <div className={styles.videoSection}>
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            webkit-playsinline="true"
            preload="auto"
            loop
            className={styles.theatreVideo}
          />
          {isPlaying && (
            <div className={styles.audioBadge}>
              <span
                className={isPaused ? styles.audioDotPaused : styles.audioDot}
              ></span>
              {isPaused ? "已暫停說明" : "小幫手說明中..."}
            </div>
          )}
          <button className={styles.controlBtn} onClick={handleTogglePlay}>
            {isPlaying && !isPaused ? "⏸ 暫停說明" : "▶️ 播放說明"}
          </button>
        </div>

        {/* 下半部內容區 */}
        <div className={styles.contentSection}>
          {step === "SELECT" && (
            <div className={styles.fadeIn}>
              <div className={styles.cardList}>
                {Object.entries(topicDescriptions).map(([key, item]) => (
                  <Card
                    key={key}
                    title={item.label}
                    description={item.description}
                    isActive={selectedKey === key}
                    onClick={() => handleSelectCard(key)}
                  />
                ))}
              </div>
              <div className={styles.buttonGroup}>
                <Button
                  onClick={() => navigate("/selection")}
                  variant="outline"
                  fullWidth
                >
                  返回重新選擇方案
                </Button>
                <Button onClick={handleConfirmTopic} fullWidth>
                  {selectedKey ? "確認選擇並查看詳情 ➔" : "請選擇一個主題"}
                </Button>
              </div>
            </div>
          )}

          {step === "INTRO" && currentTopic && (
            <div className={styles.fadeIn}>
              <Paper>
                <div
                  className={styles.introContentText}
                  dangerouslySetInnerHTML={{ __html: currentTopic.content }}
                />
              </Paper>
              <div className={styles.buttonGroupRow}>
                <Button
                  onClick={() =>
                    setSearchParams({ step: "SELECT", topic: selectedKey })
                  }
                  variant="outline"
                  style={{ flex: 1 }}
                >
                  回上一步
                </Button>
                <Button onClick={handleStartQuiz} style={{ flex: 1 }}>
                  開始了解
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SDM;
